let f;
let mouseDown = false;

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
	f = new Flock(100);
}

function draw() {
	background(0);
	f.update();
	f.draw();
}

function mousePressed() {
	mouseDown = true;
}

function mouseReleased() {
	mouseDown = false;
}

// === Tab: Fly ===
class Fly {
	constructor(x, y) {
		this.MAX_VELOCITY = 10;
		this.MAX_ACCELERATION = 0.3;
		this.position = createVector(x, y);
		this.velocity = createVector(0, 0);
		this.acceleration = createVector(0, 0);
	}

	update(target) {
		let diff = createVector(target.x, target.y);
		diff.sub(this.position);
		this.acceleration.add(diff);
		this.acceleration.normalize();
		if (this.position.x < 10) {
			this.acceleration.add(createVector(2, 0));
		}
		if (this.position.y < 10) {
			this.acceleration.add(createVector(0, 2));
		}
		if (this.position.x > width - 10) {
			this.acceleration.add(createVector(-2, 0));
		}
		if (this.position.y > height - 10) {
			this.acceleration.add(createVector(0, -2));
		}
		this.acceleration.normalize();
		this.acceleration.mult(this.MAX_ACCELERATION);
		this.acceleration.rotate(radians(random(-90, 90)));
		this.velocity.add(this.acceleration);
		if (this.velocity.mag() > this.MAX_VELOCITY) {
			this.velocity.normalize();
			this.velocity.mult(this.MAX_VELOCITY);
		}
		this.position.add(this.velocity);
	}

	draw() {
		fill(255, 255, 255);
		circle(this.position.x, this.position.y, 10);
	}
}


// === Tab: Flock ===
class Flock {
	constructor(number) {
		this.starlings = new Array(number);
		for (let i = 0; i < number; i++) {
			this.starlings[i] = new Fly(random(0, width), random(0, height));
		}
	}

	update() {
		let target = createVector(0, 0);
		let target2 = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

		if (mouseDown) {
			for (let i = 0; i < this.starlings.length; i++) {
				let targetOut = createVector(this.starlings[i].position.x, this.starlings[i].position.y);
				var diff = createVector(this.starlings[i].position.x, this.starlings[i].position.y);
				diff.sub(target2);
				targetOut.add(diff);
				this.starlings[i].update(targetOut);
			}
		} else {
			for (let i = 0; i < this.starlings.length; i++) {
				target.add(this.starlings[i].position);
			}
			target.div(this.starlings.length);
			target.add(target2);
			target.div(2);
			for (let i = 0; i < this.starlings.length; i++) {
				this.starlings[i].update(target);
			}
		}
	}

	draw() {
		for (let i = 0; i < this.starlings.length; i++) {
			this.starlings[i].draw();
		}
	}
}

